// ============================================================================
// CONFIGURACIÓN DEL BOT DE PRECIOS 0KM — es el único nodo que se toca a mano.
// ============================================================================
// Ejecución manual (botón "Execute workflow") = PRUEBA con los N modelos del
// histórico que más operaciones tienen. La ejecución semanal automática
// recorre TODOS los marca+modelo del histórico.
const esManual = $execution.mode === 'test' || $execution.mode === 'manual';

return [{
  json: {
    origen: esManual ? 'manual' : 'cron',

    // Cuántos marca+modelo buscar en una ejecución manual (0 = todos).
    limite_modelos: esManual ? 5 : 0,

    // true = busca y calcula todo, pero NO escribe en la tabla de precios 0km
    // (solo deja el log). Útil para revisar qué haría antes de dejarlo solo.
    simular: false,

    // ── Búsqueda con IA ────────────────────────────────────────────────────
    modelo_ia: 'gpt-4.1-mini',
    herramienta_busqueda: {
      type: 'web_search',
      user_location: { type: 'approximate', country: 'PE', city: 'Lima', region: 'Lima' },
    },
    // Tope de búsquedas web por modelo (cada búsqueda cuesta ~US$0.01).
    max_busquedas_por_modelo: 3,

    // ── Validación ─────────────────────────────────────────────────────────
    // Si el precio encontrado difiere más que esto del que ya está en la
    // tabla, NO se aplica: queda en el log como "salto_revision".
    umbral_cambio_pct: 15,
    precio_min_usd: 6000,
    precio_max_usd: 400000,
    // Solo si la API de tipo de cambio falla (precios publicados en soles).
    tipo_cambio_respaldo: 3.42,

    // ── Escritura en tradecars_data_precios_vehiculos_nuevos ────────────────
    // El CHECK de la columna `fuente` hoy solo acepta manual/wigo/autoland.
    // Con false: al ACTUALIZAR no se manda `fuente` (la fila conserva la
    // suya) y los modelos NUEVOS no se insertan (quedan en el log como
    // "nuevo_no_insertado"), porque `fuente` es obligatoria.
    // Poner true SOLO después de permitir 'web' en el CHECK (bloque opcional
    // de sql/tradecars_control_sync_precios.sql).
    fuente_web_permitida: false,
    fuente_valor: 'web',
    // Filas nuevas: marcadas para que un humano las revise (informativo).
    nuevo_requiere_revision: true,
    // false = nunca tocar las filas cargadas a mano (fuente = 'manual').
    actualizar_filas_manuales: true,

    supabase_url: 'https://qzmgizrvdukyxvpgclvd.supabase.co',

    // ── Costo estimado (solo para el log) ──────────────────────────────────
    costo_busqueda_usd: 0.01,
    costo_input_1m_usd: 0.40,
    costo_output_1m_usd: 1.60,

    inicio: new Date().toISOString(),
  },
}];

// ============================================================================
// Arma una búsqueda por cada marca+modelo que aparece en el histórico de
// compras/ventas (tradecars_data_historico_compras_ventas). SOLO esos: es la
// regla del pedido. El año del histórico no se usa para buscar — un 0km solo
// existe del año modelo actual.
// ============================================================================
const cfg = $('Config').first().json;

// Mismo criterio que la tool consultar_precio_nuevo del Tasador de WhatsApp:
// mayúsculas y sin tildes para guardar; sin nada no alfanumérico para comparar.
const norm = s => String(s ?? '').normalize('NFD').replace(/[̀-ͯ]/g, '')
  .toUpperCase().replace(/\s+/g, ' ').trim();
const clave = s => norm(s).replace(/[^A-Z0-9]/g, '');
// "NEW TUCSON" / "ALL NEW RIO" son el mismo modelo que "TUCSON" / "RIO".
const limpiarModelo = s => norm(s).replace(/^(ALL\s+)?NEW\s+/, '');

// ── Tipo de cambio (solo se usa si una página publica el precio en soles) ──
let tipoCambio = null;
let tipoCambioOrigen = 'respaldo_config';
try {
  const pen = Number($('Tipo de cambio').first().json?.rates?.PEN);
  if (pen > 2.5 && pen < 6) { tipoCambio = pen; tipoCambioOrigen = 'open.er-api.com'; }
} catch (e) { /* la API falló: se usa el respaldo */ }
if (!tipoCambio) tipoCambio = cfg.tipo_cambio_respaldo;

// ── Marca+modelo únicos del histórico ──
const modelos = new Map();
for (const it of $('Leer histórico').all()) {
  const marca = norm(it.json.marca);
  const modelo = limpiarModelo(it.json.modelo);
  if (!marca || !modelo || marca === 'NULL' || modelo === 'NULL') continue;
  const k = clave(marca) + '|' + clave(modelo);
  const m = modelos.get(k) || { marca, modelo, operaciones: 0 };
  m.operaciones++;
  modelos.set(k, m);
}

// ── Versiones ya registradas en la tabla 0km (para que la IA reuse el nombre) ──
const versionesPorModelo = new Map();
for (const it of $('Leer precios 0km actuales').all()) {
  const r = it.json;
  if (!r || r.id == null) continue;
  const k = clave(r.marca) + '|' + clave(r.modelo);
  if (!versionesPorModelo.has(k)) versionesPorModelo.set(k, new Set());
  if (r.version) versionesPorModelo.get(k).add(norm(r.version));
}

let lista = [...modelos.entries()].sort((a, b) => b[1].operaciones - a[1].operaciones);
if (cfg.limite_modelos > 0) lista = lista.slice(0, cfg.limite_modelos);

const anioActual = DateTime.now().setZone('America/Lima').year;

const instrucciones = `Eres un investigador de precios de autos NUEVOS (0 km) en el Perú. Usa la búsqueda web para encontrar el precio de lista ACTUAL con que se vende en el Perú el modelo que te indiquen.

Cómo buscar (hasta 3 búsquedas; detente apenas tengas precios de una fuente válida):
  a) Primero la web oficial de la marca en el Perú o su distribuidor oficial (Derco, Euromotors, Autoland, Toyota del Perú, Kia Perú, etc.).
  b) Si ahí no aparece el precio, un catálogo peruano de autos 0 km con precio de lista, como autocosmos.com.pe.
  c) No uses el operador "site:" con dominios que no conozcas con certeza: busca por texto (ej. "Hyundai Tucson precio Perú 0 km").

Reglas estrictas:
1. Solo autos NUEVOS vendidos en el PERÚ. Nunca uses precios de autos usados ni de otros países. No uses blogs, noticias, reseñas ni avisos clasificados: solo páginas de catálogo o de cotización con el precio de lista.
2. Cada precio debe salir de una página que hayas visto en la búsqueda. En "url_fuente" pon la URL exacta de esa página. Si no encontraste una página con el precio, NO lo inventes ni lo estimes.
3. "precio" es el precio de lista tal cual lo publica la página, en su moneda ("USD" o "PEN" en "moneda"). No conviertas monedas. Si solo hay un precio promocional, úsalo y marca "es_promocion": true.
4. "anio_modelo" es el año modelo que indique la página; si no lo indica, null.
5. "version" es el nombre corto de la versión o acabado como lo usa el concesionario (ej.: "LX", "EX", "GLS Full", "Limited"). Si una versión corresponde a una de las "versiones ya registradas" que te paso, escribe EXACTAMENTE ese nombre. Si el modelo tiene una sola versión, null.
6. Máximo 8 versiones, las más representativas.
7. "resultado":
   - "encontrado": encontraste al menos un precio con su página.
   - "sin_precio_publicado": no encontraste el precio (aunque el modelo se venda). Es el valor por defecto cuando no hay precio.
   - "no_se_vende_en_peru": SOLO si encontraste evidencia explícita de que ya no se vende nuevo en el Perú (la web oficial de la marca en el Perú no lo ofrece, o una nota dice que se descontinuó). No encontrar el precio NO es evidencia de eso.
   Si "resultado" no es "encontrado", "versiones" va vacío.
8. En "nota" explica en una frase de dónde salió el dato o por qué no se encontró.`;

const esquema = {
  type: 'object',
  additionalProperties: false,
  required: ['resultado', 'versiones', 'nota'],
  properties: {
    resultado: { type: 'string', enum: ['encontrado', 'sin_precio_publicado', 'no_se_vende_en_peru'] },
    nota: { type: ['string', 'null'] },
    versiones: {
      type: 'array',
      items: {
        type: 'object',
        additionalProperties: false,
        required: ['version', 'anio_modelo', 'precio', 'moneda', 'url_fuente', 'es_promocion'],
        properties: {
          version: { type: ['string', 'null'] },
          anio_modelo: { type: ['integer', 'null'] },
          precio: { type: 'number' },
          moneda: { type: 'string', enum: ['USD', 'PEN'] },
          url_fuente: { type: 'string' },
          es_promocion: { type: 'boolean' },
        },
      },
    },
  },
};

return lista.map(([k, m]) => {
  const versiones = [...(versionesPorModelo.get(k) || [])];
  const input = [
    `Marca: ${m.marca}`,
    `Modelo: ${m.modelo}`,
    `Versiones ya registradas en nuestra base: ${versiones.length ? versiones.join(', ') : 'ninguna'}`,
    `Año actual: ${anioActual}`,
  ].join('\n');

  return {
    json: {
      clave: k,
      marca: m.marca,
      modelo: m.modelo,
      operaciones_historico: m.operaciones,
      versiones_existentes: versiones,
      tipo_cambio: tipoCambio,
      tipo_cambio_origen: tipoCambioOrigen,
      _openai_body: {
        model: cfg.modelo_ia,
        instructions: instrucciones,
        input,
        tools: [cfg.herramienta_busqueda],
        max_tool_calls: cfg.max_busquedas_por_modelo,
        include: ['web_search_call.action.sources'],
        text: { format: { type: 'json_schema', name: 'precios_0km', strict: true, schema: esquema } },
      },
    },
  };
});

// ============================================================================
// Lee lo que devolvió la IA, valida cada precio y decide qué hacer con él.
//
// OJO: la tool consultar_precio_nuevo del Tasador de WhatsApp lee TODAS las
// filas de una marca+modelo, sin mirar `activa` ni `requiere_revision`. Todo
// lo que se escriba acá le llega a una cotización real. Por eso un precio solo
// se escribe si pasa TODAS las validaciones, y un cambio grande nunca se aplica
// solo: queda en el log para que un humano lo revise.
//
// Salida: un item por escritura + un item final "_plan" con el detalle
// completo. Todos pasan por "Aplicar en Supabase" (el plan hace una lectura
// inofensiva), así el flujo es lineal y el log se escribe siempre.
// ============================================================================
const cfg = $('Config').first().json;
const busquedas = $('Armar búsquedas').all();
const existentes = $('Leer precios 0km actuales').all().map(i => i.json).filter(r => r && r.id != null);

const norm = s => String(s ?? '').normalize('NFD').replace(/[̀-ͯ]/g, '')
  .toUpperCase().replace(/\s+/g, ' ').trim();
const clave = s => norm(s).replace(/[^A-Z0-9]/g, '');
// Versión "canónica": sin tokens técnicos (cilindrada, transmisión, tracción,
// combustible). "1.4L LX MT" ≈ "LX", pero "1.4L EX SPORT" ≠ "EX": una palabra
// de acabado de más (SPORT, FULL, GT…) es otra versión, no la misma.
const TECNICO = /^(\d+[LTV]?|MT|AT|CVT|DCT|IVT|TM|TA|MEC|AUT|AUTO|MANUAL|AUTOMATICO|4X2|4X4|AWD|2WD|4WD|FWD|GSL|GASOLINA|DIESEL|HEV|HIBRIDO|TURBO|L)$/;
const canonica = s => norm(s).split(/[^A-Z0-9]+/).filter(t => t && !TECNICO.test(t)).sort().join(' ');
// Sin `new URL()`: el sandbox del Code node de n8n no expone `URL` (con él,
// toda URL salía "inválida" en la primera prueba real).
const host = u => {
  const m = String(u || '').match(/^https?:\/\/([^\/?#:]+)/i);
  return m ? m[1].replace(/^www\./i, '').toLowerCase() : null;
};
const ruta = u => String(u || '').match(/^https?:\/\/[^\/?#]+(\/[^?#]*)?/i)?.[1] || '/';

const lima = DateTime.now().setZone('America/Lima');
const hoy = lima.toISODate();
const anioActual = lima.year;
const ahora = new Date().toISOString();
const tabla = `${cfg.supabase_url}/rest/v1/tradecars_data_precios_vehiculos_nuevos`;
const noop = { metodo: 'GET', url: `${tabla}?select=id&limit=1`, body: null };

function mensajeError(e) {
  if (!e) return 'sin respuesta';
  if (typeof e === 'string') return e.slice(0, 300);
  return String(e.message || e.description || JSON.stringify(e)).slice(0, 300);
}

function leerRespuesta(r) {
  if (!r || r.error) return { error: mensajeError(r?.error) };
  if (r.status && r.status !== 'completed') {
    return { error: `respuesta ${r.status}${r.incomplete_details ? ': ' + JSON.stringify(r.incomplete_details) : ''}` };
  }
  const salida = Array.isArray(r.output) ? r.output : [];
  const llamadas = salida.filter(o => o.type === 'web_search_call');
  // Páginas que la IA realmente consultó: fuentes de cada búsqueda + citas del texto.
  const fuentes = new Set();
  for (const c of llamadas) for (const s of (c.action?.sources || [])) { const h = host(s.url); if (h) fuentes.add(h); }
  let texto = '';
  for (const o of salida) {
    if (o.type !== 'message') continue;
    for (const c of (o.content || [])) {
      if (c.type !== 'output_text') continue;
      texto += c.text || '';
      for (const a of (c.annotations || [])) { const h = host(a.url); if (h) fuentes.add(h); }
    }
  }
  let datos = null;
  try { datos = JSON.parse(texto); } catch (e) {
    const m = texto.match(/\{[\s\S]*\}/);
    if (m) { try { datos = JSON.parse(m[0]); } catch (e2) { /* sigue null */ } }
  }
  const uso = r.usage || null;
  if (!datos) return { error: 'la IA no devolvió un JSON legible', busquedas_web: llamadas.length, uso };
  return { datos, fuentes, busquedas_web: llamadas.length, uso };
}

// Un artículo no es una lista de precios (en la 2.ª prueba real, un precio
// "referencial" de un blog habría pisado el de la tabla).
const RUTA_ARTICULO = /\/(blog|blogs|noticia|noticias|news|articulo|articulos|review|reviews|resena|resenas|comparativa|comparativas|prensa)(\/|$)/i;

function fuenteVerificada(url, fuentes) {
  const h = host(url);
  if (!h || !/^https?:\/\//i.test(url)) return { ok: false, motivo: 'sin URL de fuente válida' };
  if (RUTA_ARTICULO.test(ruta(url))) return { ok: false, motivo: 'la página es un artículo/blog, no una lista de precios' };
  if (fuentes.size > 0) {
    const ok = [...fuentes].some(f => h === f || h.endsWith('.' + f) || f.endsWith('.' + h));
    return ok ? { ok: true, como: 'pagina_consultada' } : { ok: false, motivo: `la URL (${h}) no está entre las páginas que la IA consultó` };
  }
  // Sin lista de fuentes: solo se acepta un dominio peruano.
  if (h.endsWith('.pe') || /^\/pe(\/|$)/i.test(ruta(url))) return { ok: true, como: 'dominio_peruano' };
  return { ok: false, motivo: 'no se pudo verificar la fuente' };
}

const escrituras = [];
const detalle = [];
let costo = 0;

$input.all().forEach((it, i) => {
  const src = (busquedas[it.pairedItem?.item ?? i] || busquedas[i]).json;
  const reg = {
    marca: src.marca,
    modelo: src.modelo,
    operaciones_historico: src.operaciones_historico,
    estado: null,
    versiones: [],
  };
  const im = detalle.length;
  detalle.push(reg);

  const r = leerRespuesta(it.json);
  reg.busquedas_web = r.busquedas_web || 0;
  if (r.uso) {
    costo += ((r.uso.input_tokens || 0) * cfg.costo_input_1m_usd + (r.uso.output_tokens || 0) * cfg.costo_output_1m_usd) / 1e6;
  }
  costo += reg.busquedas_web * cfg.costo_busqueda_usd;

  if (r.error) { reg.estado = 'error'; reg.error = r.error; return; }
  reg.nota = r.datos.nota ?? null;

  const vers = Array.isArray(r.datos.versiones) ? r.datos.versiones.slice(0, 8) : [];
  const filasDelModelo = existentes.filter(e => clave(e.marca) === clave(src.marca) && clave(e.modelo) === clave(src.modelo));
  if (r.datos.resultado !== 'encontrado' || vers.length === 0) {
    reg.estado = r.datos.resultado === 'no_se_vende_en_peru' ? 'no_se_vende_nuevo' : 'sin_precio';
    // No se marca nada como descontinuado automáticamente: queda para revisión.
    if (filasDelModelo.length) reg.aviso = `hay ${filasDelModelo.length} fila(s) de este modelo en la tabla 0km; revisar si sigue vigente`;
    return;
  }
  reg.estado = 'ok';

  const vistos = new Set();
  vers.forEach(v => {
    const out = {
      version: v.version ? norm(v.version) : null,
      anio_modelo: v.anio_modelo ?? null,
      precio_publicado: v.precio,
      moneda: v.moneda,
      url_fuente: v.url_fuente,
      es_promocion: !!v.es_promocion,
    };
    const iv = reg.versiones.length;
    reg.versiones.push(out);
    const descartar = motivo => { out.accion = 'descartado'; out.motivo = motivo; };

    const precio = Number(v.precio);
    if (!(precio > 0)) return descartar('precio inválido');
    const usd = Math.round(v.moneda === 'PEN' ? precio / src.tipo_cambio : precio);
    out.precio_usd = usd;
    if (usd < cfg.precio_min_usd || usd > cfg.precio_max_usd) {
      return descartar(`precio fuera de rango (US$${cfg.precio_min_usd}–${cfg.precio_max_usd})`);
    }
    const fv = fuenteVerificada(v.url_fuente, r.fuentes);
    if (!fv.ok) return descartar(fv.motivo);
    out.verificacion = fv.como;

    const anio = out.anio_modelo ?? anioActual;
    out.anio_modelo = anio;
    if (anio < anioActual - 1 || anio > anioActual + 1) return descartar('año modelo fuera de rango');

    const kv = clave(out.version) + '|' + anio;
    if (vistos.has(kv)) return descartar('versión repetida en la misma respuesta');
    vistos.add(kv);

    // ¿Ya existe esta marca+modelo+versión+año en la tabla?
    const cands = filasDelModelo.filter(e => Number(e.anio_modelo) === anio);
    let fila = cands.find(e => clave(e.version) === clave(out.version));
    if (!fila && out.version && canonica(out.version)) {
      // "LX" registrado ≈ "1.4L LX MT" encontrado, solo si hay UN candidato así.
      const iguales = cands.filter(e => e.version && canonica(e.version) === canonica(out.version));
      if (iguales.length === 1) fila = iguales[0];
    }

    if (fila) {
      out.fila_id = fila.id;
      out.version_en_tabla = fila.version ?? null;
      out.precio_actual_usd = Number(fila.precio_nuevo_usd);
      const delta = out.precio_actual_usd > 0 ? Math.abs(usd - out.precio_actual_usd) / out.precio_actual_usd * 100 : 0;
      out.delta_pct = Math.round(delta * 10) / 10;

      if (fila.fuente === 'manual' && !cfg.actualizar_filas_manuales) {
        out.accion = 'omitido'; out.motivo = 'fila cargada a mano (actualizar_filas_manuales = false)'; return;
      }
      if (delta > cfg.umbral_cambio_pct) {
        out.accion = 'salto_revision';
        out.motivo = `cambia ${out.delta_pct}% (umbral ${cfg.umbral_cambio_pct}%): no se aplicó, revisar a mano`;
        return;
      }
      const body = {
        precio_nuevo_usd: usd,
        moneda: 'USD',
        url_fuente: v.url_fuente,
        fecha_ultimo_precio: hoy,
        actualizado_en: ahora,
        estado_produccion: 'activo',
      };
      if (usd !== out.precio_actual_usd) body.precio_anterior_usd = out.precio_actual_usd;
      if (cfg.fuente_web_permitida) body.fuente = cfg.fuente_valor;
      out.accion = usd === out.precio_actual_usd ? 'confirmado' : 'actualizado';
      escrituras.push({ _ref: [im, iv], _http: { metodo: 'PATCH', url: `${tabla}?id=eq.${fila.id}`, body } });
      return;
    }

    if (!cfg.fuente_web_permitida) {
      out.accion = 'nuevo_no_insertado';
      out.motivo = "la columna `fuente` no acepta 'web' todavía (bloque opcional de sql/tradecars_control_sync_precios.sql)";
      return;
    }
    out.accion = 'insertado';
    escrituras.push({
      _ref: [im, iv],
      _http: {
        metodo: 'POST',
        url: tabla,
        body: {
          marca: norm(src.marca),
          modelo: norm(src.modelo),
          version: out.version,
          anio_modelo: anio,
          precio_nuevo_usd: usd,
          moneda: 'USD',
          fuente: cfg.fuente_valor,
          url_fuente: v.url_fuente,
          tier: 1,
          estado_produccion: 'activo',
          fecha_ultimo_precio: hoy,
          requiere_revision: !!cfg.nuevo_requiere_revision,
          activa: true,
          creado_por: 'bot_precios_0km_n8n',
          notas: 'Detectado por la búsqueda web semanal (n8n)',
        },
      },
    });
  });
});

const plan = {
  _plan: true,
  _http: noop,
  simular: !!cfg.simular,
  tipo_cambio: busquedas[0]?.json.tipo_cambio ?? cfg.tipo_cambio_respaldo,
  tipo_cambio_origen: busquedas[0]?.json.tipo_cambio_origen ?? 'respaldo_config',
  costo_estimado_usd: Math.round(costo * 1000) / 1000,
  detalle,
};

// En modo simulación no se escribe nada: solo sale el plan.
if (cfg.simular) return [{ json: plan }];
return [...escrituras.map(e => ({ json: e })), { json: plan }];

// ============================================================================
// Cruza el plan con el resultado real de cada escritura y arma la fila del
// log (tradecars_control_sync_precios). "Aplicar en Supabase" devuelve un
// item por cada item de "Validar y decidir", en el mismo orden.
// ============================================================================
const cfg = $('Config').first().json;
const plan = $('Validar y decidir').all();
const resultados = $input.all();

const planItem = plan.find(p => p.json._plan).json;
const detalle = planItem.detalle;

plan.forEach((p, i) => {
  if (p.json._plan) return;
  const res = resultados[i]?.json || {};
  const [im, iv] = p.json._ref;
  const v = detalle[im].versiones[iv];
  const ok = !res.error && res.statusCode >= 200 && res.statusCode < 300;
  if (!ok) {
    v.accion_planeada = v.accion;
    v.accion = 'error_escritura';
    v.error = String(res.body?.message || res.error?.message || res.statusMessage || `HTTP ${res.statusCode}`).slice(0, 300);
  } else if (Array.isArray(res.body) && res.body.length === 0) {
    // PATCH que no encontró la fila (la borraron entre la lectura y la escritura).
    v.accion_planeada = v.accion;
    v.accion = 'error_escritura';
    v.error = 'la fila ya no existe en la tabla';
  }
});

const cuenta = (pred) => detalle.reduce((n, m) => n + m.versiones.filter(pred).length, 0);
const porAccion = a => cuenta(v => v.accion === a);
const modelosConPrecio = detalle.filter(m => m.versiones.some(v => v.accion && v.accion !== 'descartado')).length;
const fallidos = detalle.filter(m => m.estado === 'error').length;

const fila = {
  origen: cfg.origen,
  simulado: !!planItem.simular,
  modelo_ia: cfg.modelo_ia,
  total_modelos: detalle.length,
  exitosos: modelosConPrecio,
  fallidos,
  sin_resultado: detalle.length - modelosConPrecio - fallidos,
  actualizados: porAccion('actualizado'),
  confirmados: porAccion('confirmado'),
  insertados: porAccion('insertado'),
  nuevos_no_insertados: porAccion('nuevo_no_insertado'),
  saltos_revision: porAccion('salto_revision'),
  descartados: porAccion('descartado'),
  errores_escritura: porAccion('error_escritura'),
  tipo_cambio_pen_usd: planItem.tipo_cambio,
  tipo_cambio_origen: planItem.tipo_cambio_origen,
  costo_estimado_usd: planItem.costo_estimado_usd,
  duracion_seg: Math.round((Date.now() - new Date(cfg.inicio).getTime()) / 1000),
  detalle_json: detalle,
};

return [{ json: { fila } }];
